(function(root){'use strict';
const fields=[{key:'plays',label:'播放量',aliases:['视频播放量','播放次数','播放量','观看次数','观看量']},{key:'completion',label:'完播率 (%)',aliases:['完播率'],percent:true},{key:'likes',label:'点赞数',aliases:['点赞数','点赞量','点赞','获赞数']},{key:'comments',label:'评论数',aliases:['评论数','评论量','评论']},{key:'saves',label:'收藏数',aliases:['收藏数','收藏量','收藏']},{key:'shares',label:'分享数',aliases:['分享数','分享量','转发数','分享','转发']},{key:'follows',label:'新增关注',aliases:['新增关注','新增粉丝','涨粉数','涨粉量']}];
const MAX_FILE=8*1024*1024,MAX_TOTAL=32*1024*1024,MAX_COUNT=8,types=['image/png','image/jpeg','image/webp'];
function numeric(text,percent=false){const s=String(text).trim().replace(/，/g,',').replace(/％/g,'%');if(/[+\-]|[><~约]/.test(s))return null;const m=s.match(/^((?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?)\s*([万千wWkK]?)\s*(%?)$/);if(!m)return null;const n=Number(m[1].replace(/,/g,'')),unit=m[2];if(percent){if(m[3]!=='%'||unit||n>100)return null;return {value:n,approx:false};}if(m[3])return null;const v=n*({万:10000,w:10000,W:10000,千:1000,k:1000,K:1000}[unit]||1);return Number.isSafeInteger(Math.round(v))&&Math.abs(v-Math.round(v))<.00001?{value:Math.round(v),approx:!!unit}:null;}
function parse(text){const lines=String(text).split(/\r?\n/).map(x=>x.trim().replace(/[：]/g,':').replace(/([\u4e00-\u9fff])\s+(?=[\u4e00-\u9fff])/g,'$1')).filter(Boolean);return fields.map(f=>{const hits=[];for(let i=0;i<lines.length;i++){for(const alias of f.aliases){const line=lines[i];let raw=null;if(line===alias||line===alias+':'){if(lines[i+1]&&numeric(lines[i+1],f.percent))raw=lines[i+1];else if(lines[i-1]&&numeric(lines[i-1],f.percent))raw=lines[i-1];}else if(line.startsWith(alias)){const rest=line.slice(alias.length);raw=rest.replace(/^[\s:]+/,'');}if(raw!==null){const n=numeric(raw,f.percent);if(n)hits.push({...n,evidence:alias+' '+raw});}}}const unique=[...new Set(hits.map(h=>h.value))];return {key:f.key,label:f.label,percent:!!f.percent,value:unique.length===1?unique[0]:null,approx:hits.some(x=>x.approx),conflict:unique.length>1,evidence:[...new Set(hits.map(h=>h.evidence))].join('；')};});}
function validateRefs(refs){if(refs===undefined)return;const ids=new Set();if(!Array.isArray(refs)||refs.length>MAX_COUNT)throw Error('截图附件数量不正确。');for(const r of refs){if(!r||typeof r.id!=='string'||!/^[-a-zA-Z0-9_]{1,100}$/.test(r.id)||ids.has(r.id)||typeof r.name!=='string'||r.name.length>300||!types.includes(r.type)||!Number.isInteger(r.size)||r.size<=0||r.size>MAX_FILE||!Number.isFinite(r.width)||r.width<=0||!Number.isFinite(r.height)||r.height<=0||typeof r.addedAt!=='string'||isNaN(Date.parse(r.addedAt)))throw Error('截图附件记录格式不正确。');if(r.ocrText!==undefined&&(typeof r.ocrText!=='string'||r.ocrText.length>60000))throw Error('识别文字格式不正确。');ids.add(r.id);}}
function validateProject(p){validateRefs(p.metricScreenshots);if(p.metricEntryDraft){const allowed=['platform','publishedAt','publishUrl','window','plays','completion','likes','comments','saves','shares','follows','source','collectedAt'];if(typeof p.metricEntryDraft!=='object'||Object.entries(p.metricEntryDraft).some(([k,v])=>!allowed.includes(k)||typeof v!=='string'||v.length>2000))throw Error('数据录入草稿格式不正确。');}}
const api={fields,numeric,parse,validateRefs,validateProject,MAX_FILE,MAX_TOTAL,MAX_COUNT,types};root.JimuEvidence=api;if(typeof module!=='undefined')module.exports=api;
})(globalThis);
